/**
 * The mark, as raster bytes.
 *
 * The favicon was an inline SVG data URI on every page, plus a /favicon.ico
 * route that answered the browser's implicit probe with the same SVG under
 * `image/svg+xml`. On Chrome that works. On Safari it does not: Safari does
 * not render SVG favicons, so it falls back to /favicon.ico — and what came
 * back was SVG bytes at a path that promises an icon format, which it cannot
 * decode. The tab then shows the browser's own placeholder, which is what a
 * visitor was actually seeing next to the address bar.
 *
 * So the probe gets a real PNG. This is the floor underneath the link tags.
 *
 * These are the actual Paisa mark — the orange tile with the stylised P —
 * rendered from the same public/logo.png the header and the answer avatars
 * use, so there is one mark rather than three that drift. The tile is square
 * here: its own rounded corners were cropped away with its edges, and at the
 * sizes a tab and a home screen render it, a browser's own rounding is what
 * shows anyway.
 */
export const FAVICON_PNG = Buffer.from(
  "",
  "base64",
);

export const APPLE_TOUCH_PNG = Buffer.from(
  "",
  "base64",
);
